function envStr(name, fallback) {
  try {
    var v = $env[name];
    if (v === undefined || v === null || v === '') { return fallback; }
    return String(v);
  } catch (e) {
    return fallback;
  }
}
function pick(v, envName, fallback) {
  if (v !== undefined && v !== null && v !== '') { return v; }
  return envStr(envName, fallback);
}

var out = [];
var items = $input.all();
for (var i = 0; i < items.length; i++) {
  var j = items[i].json || {};
  var runKey = j.run_key;
  if (runKey === undefined || runKey === null || runKey === '') { runKey = $execution.id; }
  out.push({ json: {
    workflow_key: String(pick(j.workflow_key, 'N8N_CB_WORKFLOW_KEY', 'default')),
    run_key: String(runKey),
    max_iterations: Number(pick(j.max_iterations, 'N8N_CB_MAX_ITERATIONS', '25')),
    max_runtime_ms: Number(pick(j.max_runtime_ms, 'N8N_CB_MAX_RUNTIME_MS', '300000'))
  } });
}
return out;

var cfg = $('Normalize Budget Input').first().json;
var row = $input.first().json || {};
var iterations = Number(row.iterations || 0);
var elapsed = Number(row.elapsed_ms || 0);
var overIter = iterations > Number(cfg.max_iterations);
var overTime = elapsed > Number(cfg.max_runtime_ms);
var reasons = [];
if (overIter) { reasons.push('iteration budget exceeded: ' + iterations + ' of ' + cfg.max_iterations); }
if (overTime) { reasons.push('wall-clock budget exceeded: ' + elapsed + ' ms of ' + cfg.max_runtime_ms + ' ms'); }
return [{ json: {
  workflow_key: cfg.workflow_key,
  run_key: cfg.run_key,
  iterations: iterations,
  max_iterations: Number(cfg.max_iterations),
  elapsed_ms: elapsed,
  max_runtime_ms: Number(cfg.max_runtime_ms),
  iterations_remaining: Number(cfg.max_iterations) - iterations,
  over_budget: overIter || overTime,
  reason: reasons.length > 0 ? reasons.join('; ') : 'within iteration and time budget'
} }];

// Build one alert payload. Wire the NEXT node to Slack / email / PagerDuty.
var j = $input.first().json || {};
return [{ json: {
  alert: true,
  severity: 'critical',
  module: 'iteration-budget',
  workflow_key: j.workflow_key || 'unknown',
  reason: j.reason || 'limit exceeded',
  detail: j,
  execution_id: $execution.id,
  fired_at: new Date().toISOString()
} }];
